import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BZO4qERu.js";const q=JSON.parse('{"title":"言语理解与表达","description":"","frontmatter":{},"headers":[],"relativePath":"xingce/yanyu-lijie.md","filePath":"xingce/yanyu-lijie.md"}'),l={name:"xingce/yanyu-lijie.md"};function d(i,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="言语理解与表达" tabindex="-1">言语理解与表达 <a class="header-anchor" href="#言语理解与表达" aria-label="Permalink to &quot;言语理解与表达&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>言语理解与表达是行测中题量最大的模块，考察对语言文字的理解和运用能力。</p><h2 id="📊-题型分布-国考" tabindex="-1">📊 题型分布（国考） <a class="header-anchor" href="#📊-题型分布-国考" aria-label="Permalink to &quot;📊 题型分布（国考）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题型</th><th>题量</th><th>建议用时</th></tr></thead><tbody><tr><td>逻辑填空</td><td>15-20</td><td>12-15 分钟</td></tr><tr><td>阅读理解</td><td>15-20</td><td>12-15 分钟</td></tr><tr><td>语句表达</td><td>5-8</td><td>5-8 分钟</td></tr></tbody></table><hr><h2 id="一、逻辑填空-选词填空" tabindex="-1">一、逻辑填空（选词填空） <a class="header-anchor" href="#一、逻辑填空-选词填空" aria-label="Permalink to &quot;一、逻辑填空（选词填空）&quot;">​</a></h2><h3 id="解题步骤" tabindex="-1">解题步骤 <a class="header-anchor" href="#解题步骤" aria-label="Permalink to &quot;解题步骤&quot;">​</a></h3><ol><li><strong>通读全文</strong> → 把握语境和感情色彩</li><li><strong>分析空缺处逻辑关系</strong> → 并列/转折/递进/因果/解释</li><li><strong>辨析词义</strong> → 从选项中选择最合适的</li></ol><h3 id="常见逻辑关系" tabindex="-1">常见逻辑关系 <a class="header-anchor" href="#常见逻辑关系" aria-label="Permalink to &quot;常见逻辑关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>标志词</th><th>解题要点</th></tr></thead><tbody><tr><td>并列</td><td>和、与、同时、既...又...</td><td>前后语义相近</td></tr><tr><td>转折</td><td>但、却、然而、不过</td><td>前后语义相反</td></tr><tr><td>递进</td><td>甚至、更、尤其</td><td>后比前更深一层</td></tr><tr><td>因果</td><td>因为、所以、因此</td><td>前后有因果关联</td></tr><tr><td>解释</td><td>也就是说、换言之</td><td>前后语义相同</td></tr></tbody></table><h3 id="高频易混词辨析" tabindex="-1">高频易混词辨析 <a class="header-anchor" href="#高频易混词辨析" aria-label="Permalink to &quot;高频易混词辨析&quot;">​</a></h3><details class="details custom-block"><summary>📝 我常搞混的词（持续更新）</summary><table tabindex="0"><thead><tr><th>词语</th><th>含义</th><th>适用场景</th></tr></thead><tbody><tr><td>推脱 / 推托</td><td>推脱=推卸责任 / 推托=借故拒绝</td><td>①他有错不认，一味<strong>推脱</strong> ②他以生病为<strong>推托</strong>没来</td></tr><tr><td>必需 / 必须</td><td>必需=不可缺少的东西 / 必须=一定要</td><td>①水是生活<strong>必需</strong>品 ②<strong>必须</strong>完成</td></tr><tr><td>遏制 / 遏止</td><td>遏制=控制住 / 遏止=使其停止</td><td>①<strong>遏制</strong>疫情蔓延 ②<strong>遏止</strong>暴力行为</td></tr></tbody></table></details><hr><h2 id="二、阅读理解" tabindex="-1">二、阅读理解 <a class="header-anchor" href="#二、阅读理解" aria-label="Permalink to &quot;二、阅读理解&quot;">​</a></h2><h3 id="主旨概括题" tabindex="-1">主旨概括题 <a class="header-anchor" href="#主旨概括题" aria-label="Permalink to &quot;主旨概括题&quot;">​</a></h3><p><strong>核心方法</strong>：找中心句 → 提炼主题词 → 匹配选项</p><blockquote><p>💡 中心句常见位置：段首、段尾、转折后、总结性词语后</p></blockquote><p><strong>快速定位技巧</strong>：</p><ul><li>🚩 &quot;因此&quot;&quot;所以&quot;&quot;可见&quot;后面的往往是主旨</li><li>🚩 &quot;但是&quot;&quot;然而&quot;&quot;不过&quot;之后往往是重点</li><li>🚩 首句提出话题 + 末句回扣 = 总分总结构</li></ul><h3 id="细节判断题" tabindex="-1">细节判断题 <a class="header-anchor" href="#细节判断题" aria-label="Permalink to &quot;细节判断题&quot;">​</a></h3><p>逐项对照原文，注意偷换概念、无中生有、绝对化表述</p><h3 id="推断题" tabindex="-1">推断题 <a class="header-anchor" href="#推断题" aria-label="Permalink to &quot;推断题&quot;">​</a></h3><p>基于原文合理推断，不选原文直接复述的选项</p><hr><h2 id="三、语句表达" tabindex="-1">三、语句表达 <a class="header-anchor" href="#三、语句表达" aria-label="Permalink to &quot;三、语句表达&quot;">​</a></h2><h3 id="语句排序" tabindex="-1">语句排序 <a class="header-anchor" href="#语句排序" aria-label="Permalink to &quot;语句排序&quot;">​</a></h3><ol><li>先看选项首句，排除不适合做开头的</li><li>找关联词配对（虽然...但是...、不仅...而且...）</li><li>找指代词回溯（&quot;这&quot;&quot;那&quot;&quot;其&quot;前面一定有指代对象）</li><li>按时间/逻辑顺序排列</li></ol><h3 id="语句填空" tabindex="-1">语句填空 <a class="header-anchor" href="#语句填空" aria-label="Permalink to &quot;语句填空&quot;">​</a></h3><p>根据空缺位置判断：</p><ul><li><strong>段首</strong> → 总起下文</li><li><strong>段中</strong> → 承上启下</li><li><strong>段尾</strong> → 总结全文</li></ul><hr><h2 id="📝-我的备考笔记" tabindex="-1">📝 我的备考笔记 <a class="header-anchor" href="#📝-我的备考笔记" aria-label="Permalink to &quot;📝 我的备考笔记&quot;">​</a></h2><h3 id="常犯错误" tabindex="-1">常犯错误 <a class="header-anchor" href="#常犯错误" aria-label="Permalink to &quot;常犯错误&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="技巧心得" tabindex="-1">技巧心得 <a class="header-anchor" href="#技巧心得" aria-label="Permalink to &quot;技巧心得&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to &quot;🔗 相关资源&quot;">​</a></h2><ul><li>粉笔 App 言语理解专项练习</li><li>历年国考/省考真题</li></ul>',40)])])}const b=a(l,[["render",d]]);export{q as __pageData,b as default};
